/** Korean copula after a word: 비 → 예요, 구름 → 이에요. */
const iya = (w: string) => { const c = w.charCodeAt(w.length - 1) - 0xac00; return c >= 0 && c < 11172 && c % 28 === 0 ? '예요' : '이에요'; };

